//! Skel codec checked against blobs read from real wc.db files written by svn 1.15.0
//! (NODES/ACTUAL_NODE `properties`, `inherited_props`, WORK_QUEUE `work` and
//! ACTUAL_NODE `conflict_data`). Every blob must round-trip byte for byte.
#![allow(clippy::expect_used, clippy::panic)]

use svn_wc::skel::{self, Skel};

fn unhex(h: &str) -> Vec<u8> {
    (0..h.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&h[i..i + 2], 16).expect("hex"))
        .collect()
}

fn assert_roundtrip(label: &str, hex: &str) -> Skel {
    let blob = unhex(hex);
    let parsed = Skel::parse(&blob).unwrap_or_else(|e| panic!("{label}: {e}"));
    assert_eq!(parsed.unparse(), blob, "{label}: not byte-identical");
    parsed
}

