/// (label, hex) pairs of conflict_data skels (text, prop and tree conflicts from an update).
const CONFLICT_BLOBS: &[(&str, &str)] = &[
    (
        "f.txt",
        "",
    ),
    (
        "d",
        "",
    ),
    (
        "g.txt",
        "",
    ),
];

#[test]
fn property_blobs_roundtrip_and_parse_as_proplists() {
    for (label, hex) in PROPERTY_BLOBS {
        let skel = assert_roundtrip(label, hex);
        if label.starts_with("iprops") {
            skel::parse_iprops(&skel).expect("iprops");
        } else {
            let props = skel::parse_proplist(&skel).expect("proplist");
            assert_eq!(skel::unparse_proplist(&props), skel, "{label}");
        }
    }
}

#[test]
fn property_blob_values_decode() {
    let (_, hex) = PROPERTY_BLOBS
        .iter()
        .find(|(l, _)| *l == "props:c.txt")
        .expect("c.txt props present");
    let props = skel::parse_proplist(&Skel::parse(&unhex(hex)).expect("parse")).expect("props");
    assert!(props.contains(&(b"svn:keywords".to_vec(), b"Id Rev".to_vec())));
    assert!(props.contains(&(b"svn:executable".to_vec(), b"*".to_vec())));
}

#[test]
fn work_queue_blobs_roundtrip_with_known_opcodes() {
    let known = [
        "file-install",
        "file-remove",
        "file-translate",
        "sync-file-flags",
        "prej-install",
        "dir-install",
        "file-commit",
    ];
    let mut seen = std::collections::BTreeSet::new();
    for (label, hex) in WORK_QUEUE_BLOBS {
        let skel = assert_roundtrip(label, hex);
        let items = skel.as_list().expect("work item is a list");
        let op = items[0].as_atom().expect("opcode atom");
        let op = String::from_utf8_lossy(op).into_owned();
        assert!(
            known.contains(&op.as_str()),
            "{label}: unexpected opcode {op}"
        );
        seen.insert(op);
    }
    for op in [
        "file-install",
        "file-remove",
        "file-translate",
        "sync-file-flags",
        "file-commit",
    ] {
        assert!(seen.contains(op), "fixture lacks {op}");
    }
}

#[test]
fn conflict_blobs_roundtrip() {
    assert!(CONFLICT_BLOBS.len() >= 3);
    for (label, hex) in CONFLICT_BLOBS {
        let skel = assert_roundtrip(label, hex);
        // ((conflict-kinds...) ...) outer list; first child is the operation or kind list
        assert!(skel.as_list().is_some_and(|l| !l.is_empty()), "{label}");
    }
}
